import django.db.models.deletion
from django.db import migrations, models
from django.db.models import Q


def link_existing_cash_payments(apps, schema_editor):
    """
    Attach existing cash payments to the session they were previously
    counted in (same branch + same user + inside the session's time window),
    so open sessions reconcile the same way after this migration.
    """
    Payment = apps.get_model("payments", "Payment")
    CashSession = apps.get_model("cash_management", "CashSession")

    for payment in Payment.objects.filter(
        method="cash", cash_session__isnull=True,
    ).select_related("sale"):
        session = (
            CashSession.objects.filter(
                branch_id=payment.sale.branch_id,
                cashier_id=payment.received_by_id,
                opened_at__lte=payment.created_at,
            )
            .filter(Q(closed_at__isnull=True) | Q(closed_at__gte=payment.created_at))
            .order_by("-opened_at")
            .first()
        )
        if session:
            payment.cash_session_id = session.pk
            payment.save(update_fields=["cash_session"])


